package vn.edu.hcmute.example3;
import org.slf4j.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.mail.SimpleMailMessage; import org.springframework.mail.javamail.JavaMailSender; import org.springframework.stereotype.Component;
@Component class OtpSender {private static final Logger log=LoggerFactory.getLogger(OtpSender.class);private final JavaMailSender mail;private final boolean enabled;OtpSender(JavaMailSender mail,@Value("${app.mail.enabled:false}")boolean enabled){this.mail=mail;this.enabled=enabled;}void send(String email,String code,String purpose){if(!enabled){log.info("Mã xác nhận {} cho {}: {}",purpose,email,code);return;}var message=new SimpleMailMessage();message.setTo(email);message.setSubject("Mã xác nhận Góc Sách");message.setText("Mã xác nhận của bạn là "+code+". Mã có hiệu lực trong 10 phút.");mail.send(message);}}
